// ---- อ้างอิงทะเบียนสารส่วนประกอบอาหาร อย. (อ่านอย่างเดียว) — ตารางสร้างและเติมข้อมูลอัตโนมัติครั้งแรกที่ใช้งาน
let _fdaRefReady = false;
async function ensureFdaRef(env) {
  if (_fdaRefReady) return;
  await env.DB.prepare('CREATE TABLE IF NOT EXISTS fda_ingredient_ref (fda_number TEXT PRIMARY KEY, name_th TEXT NOT NULL DEFAULT \'\', name_en TEXT NOT NULL DEFAULT \'\', type TEXT NOT NULL DEFAULT \'\', ins_no TEXT NOT NULL DEFAULT \'\', grp TEXT NOT NULL DEFAULT \'\', source TEXT NOT NULL DEFAULT \'\', note TEXT NOT NULL DEFAULT \'\')').run();
  const n = await env.DB.prepare('SELECT COUNT(*) AS n FROM fda_ingredient_ref').first();
  if (!n || !n.n) {
    const ins = 'INSERT OR IGNORE INTO fda_ingredient_ref (fda_number, name_th, name_en, type, ins_no, grp, source, note) VALUES (?, ?, ?, ?, ?, ?, ?, ?)';
    for (let i = 0; i < FDA_SEED.length; i += 50) {
      await env.DB.batch(FDA_SEED.slice(i, i + 50).map((r) => env.DB.prepare(ins).bind(r.f, r.th, r.en, r.t, r.i, r.grp, r.src, r.note)));
    }
  }
  _fdaRefReady = true;
}
const MATERIAL_SELECT = 'SELECT m.*, r.name_th AS fda_ref_name_th, r.name_en AS fda_ref_name_en, r.type AS fda_ref_type, r.ins_no AS fda_ref_ins FROM ra_raw_material_master m LEFT JOIN fda_ingredient_ref r ON r.fda_number = m.fda_ref_number';

