const RELOC_STATUS = ['TODO', 'DOING', 'WAIT', 'DONE'];
let _relocReady = false;
async function ensureReloc(env) {
  if (_relocReady) return;
  await env.DB.batch([
    env.DB.prepare("CREATE TABLE IF NOT EXISTS reg_reloc_items (id TEXT PRIMARY KEY, kind TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 0, data TEXT NOT NULL DEFAULT '{}', updated_by TEXT, updated_at TEXT)"),
    env.DB.prepare("CREATE TABLE IF NOT EXISTS reg_reloc_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL DEFAULT '')"),
  ]);
  const n = await env.DB.prepare('SELECT COUNT(*) AS n FROM reg_reloc_items').first();
  if (!n || !n.n) {
    const st = RELOC_TASKS.map(([g, t], i) => env.DB.prepare("INSERT OR IGNORE INTO reg_reloc_items (id, kind, sort, data) VALUES (?, 'TASK', ?, ?)")
      .bind('T' + String(i + 1).padStart(2, '0'), i, JSON.stringify({ group: g, title: t, status: g === 'รอหลังย้าย' ? 'WAIT' : 'TODO', due: '', note: '' })));
    const prods = await env.DB.prepare("SELECT id, json_extract(data,'$.productCode') code, json_extract(data,'$.thaiProductName') name, json_extract(data,'$.thaiFdaNumber') fda FROM reg_records WHERE collection = 'regProducts' ORDER BY id").all();
    prods.results.forEach((r, i) => st.push(env.DB.prepare("INSERT OR IGNORE INTO reg_reloc_items (id, kind, sort, data) VALUES (?, 'PRODUCT', ?, ?)")
      .bind('P-' + r.id, 100 + i, JSON.stringify({ productId: r.id, code: r.code || '', name: r.name || '', oldFda: r.fda || '', newFda: '', applied: false, artwork: false, lab: false, oldLabelEnd: '', note: '' }))));
    st.push(env.DB.prepare("INSERT OR IGNORE INTO reg_reloc_settings (key, value) VALUES ('window', 'ปลาย พ.ย. – ต้น ธ.ค. 2569 (ยังไม่มีกำหนดแน่นอน)'), ('moveDate', '')"));
    await env.DB.batch(st);
  }
  _relocReady = true;
}

