const WATCH_STATUS = ['DRAFT', 'PUBLISHED', 'EFFECTIVE', 'CLOSED'];
let _watchReady = false;
async function ensureWatch(env) {
  if (_watchReady) return;
  await env.DB.prepare("CREATE TABLE IF NOT EXISTS reg_watch (id TEXT PRIMARY KEY, title TEXT NOT NULL, ref TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'DRAFT', published_date TEXT NOT NULL DEFAULT '', effective_date TEXT NOT NULL DEFAULT '', grace TEXT NOT NULL DEFAULT '', summary TEXT NOT NULL DEFAULT '[]', impacts TEXT NOT NULL DEFAULT '[]', source TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', updated_by TEXT, updated_at TEXT)").run();
  const n = await env.DB.prepare('SELECT COUNT(*) AS n FROM reg_watch').first();
  if (!n || !n.n) {
    await env.DB.batch(WATCH_SEED.map((w) => env.DB.prepare('INSERT OR IGNORE INTO reg_watch (id, title, ref, status, published_date, effective_date, grace, summary, impacts, source) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)')
      .bind(w.id, w.title, w.ref, w.status, w.published, w.effective, w.grace, JSON.stringify(w.summary), JSON.stringify(w.impacts), w.source)));
  }
  _watchReady = true;
}
