// ---------------------------------------------------------------- preservative + sodium screening (from weigh sheet 16/10/2026)
const PC_SOURCE = 'ประกาศ สธ. (ฉบับที่ 468) พ.ศ. 2568 บัญชีหมายเลข 1 หน้า 80–83 (เบนโซเอต) และ 646–650 (ซอร์เบต) · คัดลอกจากไฟล์ Weigh Sheet Summary 16/10/2026 · รอ QA/RA ตรวจเทียบประกาศฉบับจริง';
let _pcReady = false;
async function ensurePc(env) {
  if (_pcReady) return;
  await env.DB.batch([
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_limits (cat_code TEXT PRIMARY KEY, cat_name TEXT NOT NULL, benzoate_max REAL NOT NULL, sorbate_max REAL NOT NULL, note TEXT NOT NULL DEFAULT \'\', source TEXT NOT NULL DEFAULT \'\')'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_sodium (name TEXT PRIMARY KEY, mg100g REAL, status TEXT NOT NULL DEFAULT \'MISSING\', note TEXT NOT NULL DEFAULT \'\', updated_by TEXT, updated_at TEXT)'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, fda_number TEXT NOT NULL, ingredient TEXT NOT NULL, total_kg REAL NOT NULL)'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_product (fda_number TEXT PRIMARY KEY, product_name TEXT NOT NULL, weigh_date TEXT NOT NULL DEFAULT \'\', batches INTEGER NOT NULL DEFAULT 1, category_code TEXT NOT NULL DEFAULT \'\', finished_kg REAL, cat_note TEXT NOT NULL DEFAULT \'\')'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_settings (key TEXT PRIMARY KEY, value REAL NOT NULL, note TEXT NOT NULL DEFAULT \'\')'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_claim (fda_number TEXT NOT NULL, claim TEXT NOT NULL, PRIMARY KEY (fda_number, claim))'),
    env.DB.prepare('CREATE TABLE IF NOT EXISTS reg_pc_lab (id INTEGER PRIMARY KEY AUTOINCREMENT, fda_number TEXT NOT NULL, lab TEXT NOT NULL, report_no TEXT NOT NULL, sample_name TEXT NOT NULL DEFAULT \'\', report_date TEXT NOT NULL DEFAULT \'\', sodium_mg100g REAL, potassium_mg100g REAL, note TEXT NOT NULL DEFAULT \'\', fat_g100 REAL, satfat_g100 REAL, sugar_g100 REAL, chol_mg100 REAL)'),
  ]);
  const n = await env.DB.prepare('SELECT COUNT(*) AS n FROM reg_pc_product').first();
  if (!n || !n.n) {
    const st = [];
    for (const r of PC_SEED.lim) st.push(env.DB.prepare('INSERT OR IGNORE INTO reg_pc_limits (cat_code, cat_name, benzoate_max, sorbate_max, note, source) VALUES (?, ?, ?, ?, ?, ?)').bind(r[0], r[1], r[2], r[3], r[4], PC_SOURCE));
    for (const r of PC_SEED.sod) st.push(env.DB.prepare('INSERT OR IGNORE INTO reg_pc_sodium (name, mg100g, status, note) VALUES (?, ?, ?, ?)').bind(r[0], r[1], r[2], r[3]));
    for (const r of PC_SEED.lines) st.push(env.DB.prepare('INSERT INTO reg_pc_lines (fda_number, ingredient, total_kg) VALUES (?, ?, ?)').bind(r[0], r[1], r[2]));
    for (const r of PC_SEED.prods) st.push(env.DB.prepare('INSERT OR IGNORE INTO reg_pc_product (fda_number, product_name, weigh_date, batches, category_code, cat_note) VALUES (?, ?, ?, ?, ?, ?)').bind(r.f, r.p, r.d, r.b, r.g, r.n));
    st.push(env.DB.prepare("INSERT OR IGNORE INTO reg_pc_settings (key, value, note) VALUES ('benzoate_to_acid', 0.847, 'โซเดียมเบนโซเอต → กรดเบนโซอิก (122.12/144.10) ประกาศ 468 หมายเหตุ 13')"));
    st.push(env.DB.prepare("INSERT OR IGNORE INTO reg_pc_settings (key, value, note) VALUES ('sorbate_to_acid', 0.746, 'โพแทสเซียมซอร์เบต → กรดซอร์บิก (112.13/150.22) ประกาศ 468 หมายเหตุ 42')"));
    st.push(env.DB.prepare("INSERT OR IGNORE INTO reg_pc_settings (key, value, note) VALUES ('low_sodium', 120, 'เกณฑ์โซเดียมต่ำ มก./100 ก. ของผลิตภัณฑ์ — ยังไม่ยืนยันกับบัญชีท้ายประกาศ 445 (ทางเลือก 120 / 233 / 467)')"));
    for (let i = 0; i < st.length; i += 80) await env.DB.batch(st.slice(i, i + 80));
  }
  _pcReady = true;
}

// ประกาศ สธ. 445 บัญชีหมายเลข 1 ข้อ 2.6: rounding of label values
function r445(kind, v) {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  if (kind === 'g') return v < 0.5 ? 0 : v < 5 ? Math.round(v * 2) / 2 : Math.round(v);
  if (kind === 'sugar') return v < 0.5 ? 0 : v < 1 ? 0.9 : Math.round(v);
  if (kind === 'na') return v < 5 ? 0 : v <= 140 ? Math.round(v / 5) * 5 : Math.round(v / 10) * 10;
  if (kind === 'chol') return v < 2 ? 0 : v < 5 ? 4.9 : Math.round(v / 5) * 5;
  return v;
}
// ประกาศ 445 บัญชีหมายเลข 4 ข้อ 2.2: nutrient levels that must be disclosed next to any claim
const PC_DISCLOSE = [
  { key: 'fat', label: 'ไขมันทั้งหมด', unit: 'ก.', max: 13, kind: 'g' },
  { key: 'sat', label: 'ไขมันอิ่มตัว', unit: 'ก.', max: 4, kind: 'g' },
  { key: 'chol', label: 'คอเลสเตอรอล', unit: 'มก.', max: 60, kind: 'chol' },
  { key: 'na', label: 'โซเดียม', unit: 'มก.', max: 300, kind: 'na' },
  { key: 'sugar', label: 'น้ำตาลทั้งหมด', unit: 'ก.', max: 13, kind: 'sugar' },
];
async function pcCompute(env) {
  await ensurePc(env);
  const [lim, sod, lines, prods, sets, labs, claims] = await Promise.all([
    env.DB.prepare('SELECT * FROM reg_pc_limits ORDER BY cat_code').all(),
    env.DB.prepare('SELECT * FROM reg_pc_sodium ORDER BY (mg100g IS NOT NULL), name').all(),
    env.DB.prepare('SELECT fda_number, ingredient, total_kg FROM reg_pc_lines ORDER BY id').all(),
    env.DB.prepare('SELECT * FROM reg_pc_product ORDER BY fda_number').all(),
    env.DB.prepare('SELECT key, value, note FROM reg_pc_settings').all(),
    env.DB.prepare('SELECT * FROM reg_pc_lab ORDER BY report_date, id').all(),
    env.DB.prepare('SELECT fda_number, claim FROM reg_pc_claim ORDER BY fda_number').all(),
  ]);
  const labBy = {};
  for (const l of labs.results) labBy[l.fda_number] = l; // latest report per product
  const S = Object.fromEntries(sets.results.map((r) => [r.key, r.value]));
  const limBy = Object.fromEntries(lim.results.map((r) => [r.cat_code, r]));
  const sodBy = Object.fromEntries(sod.results.map((r) => [r.name, r]));
  const verdict = (mg, perKg, max) => (mg === 0 ? 'ไม่ใช้' : max === undefined ? 'ตรวจหมวด' : max === 0 ? 'ไม่อนุญาตในหมวดนี้' : perKg > max ? 'เกิน' : 'ไม่เกิน');
  const products = prods.results.map((p) => {
    const ls = lines.results.filter((l) => l.fda_number === p.fda_number).map((l) => {
      const kg = l.total_kg / (p.batches || 1);
      const pres = l.ingredient === 'เบนโซเอต' ? 'benz' : l.ingredient === 'โปแตสเซียม' ? 'sorb' : '';
      const ref = sodBy[l.ingredient];
      const na = ref && ref.mg100g !== null ? ref.mg100g : null;
      return { ingredient: l.ingredient, kgPerBatch: kg, pres, sodiumMg100g: na, sodiumStatus: ref ? ref.status : 'MISSING', sodiumMgBatch: na === null ? 0 : kg * 10 * na };
    });
    const rawKg = ls.reduce((a, l) => a + l.kgPerBatch, 0);
    const baseKg = p.finished_kg > 0 ? p.finished_kg : rawKg;
    const benzMg = ls.filter((l) => l.pres === 'benz').reduce((a, l) => a + l.kgPerBatch * 1e6 * S.benzoate_to_acid, 0);
    const sorbMg = ls.filter((l) => l.pres === 'sorb').reduce((a, l) => a + l.kgPerBatch * 1e6 * S.sorbate_to_acid, 0);
    const lm = limBy[p.category_code];
    const naMg = ls.reduce((a, l) => a + l.sodiumMgBatch, 0);
    const naEst = baseKg > 0 ? naMg / (baseKg * 10) : 0;
    const lab = labBy[p.fda_number] || null;
    const naPer100 = lab && lab.sodium_mg100g !== null ? lab.sodium_mg100g : naEst; // measured value wins over the estimate
    const missing = ls.filter((l) => l.sodiumMg100g === null).map((l) => l.ingredient);
    const servingG = S['serving_g:' + p.fda_number] > 0 ? S['serving_g:' + p.fda_number] : 20; // label serving size (g); default 20 g
    // โซเดียมต่ำ: "น้อยกว่า 140 มก." ต่อปริมาณที่กินต่อครั้งบนฉลาก และต่อ 2 เท่าของหน่วยบริโภคอ้างอิง (บัญชี 4 ข้อ 2.1 กรณีที่ 1 ข้อ 2), ตารางที่ 1)
    const naServ = naPer100 * servingG / 100, naClaim = naPer100 * servingG * 2 / 100;
    const naPass = naServ < S.low_sodium && naClaim < S.low_sodium;
    const naRes = naPass ? (lab ? 'PASS' : 'PASS_PARTIAL') : 'FAIL';
    const disclose = [];
    if (lab) {
      const per100 = { fat: lab.fat_g100, sat: lab.satfat_g100, chol: lab.chol_mg100, na: lab.sodium_mg100g, sugar: lab.sugar_g100 };
      for (const d of PC_DISCLOSE) {
        if (per100[d.key] === null || per100[d.key] === undefined) continue;
        const atServ = r445(d.kind, per100[d.key] * servingG / 100), atClaim = r445(d.kind, per100[d.key] * servingG * 2 / 100);
        if (atClaim > d.max || atServ > d.max) disclose.push({ label: d.label, unit: d.unit, max: d.max, serving: atServ, double: atClaim });
      }
    }
    return {
      fda: p.fda_number, name: p.product_name, weighDate: p.weigh_date, batches: p.batches, category: p.category_code, catNote: p.cat_note,
      finishedKg: p.finished_kg, rawKg, baseKg, baseType: p.finished_kg > 0 ? 'FINISHED' : 'RAW_MIN',
      benzMg, benzMgKg: baseKg > 0 ? benzMg / baseKg : 0, benzMax: lm ? lm.benzoate_max : null, benzResult: verdict(benzMg, baseKg > 0 ? benzMg / baseKg : 0, lm ? lm.benzoate_max : undefined),
      sorbMg, sorbMgKg: baseKg > 0 ? sorbMg / baseKg : 0, sorbMax: lm ? lm.sorbate_max : null, sorbResult: verdict(sorbMg, baseKg > 0 ? sorbMg / baseKg : 0, lm ? lm.sorbate_max : undefined),
      sodiumMg: naMg, sodiumMg100g: naPer100, sodiumEstimate: naEst, sodiumResult: naRes, servingG, servingNa: naServ, claimG: servingG * 2, claimNa: naClaim, claimLimitNa: S.low_sodium, servingNaLabel: r445('na', naServ), claimNaLabel: r445('na', naClaim), disclose, labMissingNutrients: lab ? [lab.fat_g100, lab.satfat_g100, lab.sugar_g100].some((v) => v === null) : false, servingFromLabel: S['serving_g:' + p.fda_number] > 0, labelNa: S['label_na:' + p.fda_number] >= 0 ? S['label_na:' + p.fda_number] : null, missing, lines: ls,
      lab: lab ? { lab: lab.lab, reportNo: lab.report_no, sampleName: lab.sample_name, reportDate: lab.report_date, sodium: lab.sodium_mg100g, potassium: lab.potassium_mg100g, note: lab.note } : null,
    };
  });
  return { settings: S, limits: lim.results, sodium: sod.results, products, claims: claims.results.map((c) => ({ fda: c.fda_number, claim: c.claim })), source: PC_SOURCE };
}

export default {
  async fetch(request, env)                    {
    const url = new URL(request.url);
    if (!url.pathname.startsWith('/api/')) return serveStatic(request);
    try {
      return await handleApi(request, env, url);
    } catch (e) {
      if (e instanceof HttpError) return json({ error: { code: e.code, message: e.message } }, e.status);
      const message = String((e         )?.message || e);
      // D1 trigger messages (second line of defence) are shown to the user as conflicts
      if (message.includes('LOCKED:')) return json({ error: { code: 'LOCKED', message: message.split('LOCKED:')[1].trim() } }, 409);
      console.error('API_ERROR', url.pathname, message);
      return json({ error: { code: 'INTERNAL', message: 'เกิดข้อผิดพลาดในระบบ กรุณาลองใหม่' } }, 500);
    }
  },
}                               ;
